#!/bin/sh
# The plesiosaur as one beast round the board (GulpView, second pass): his head in three-quarter view over the board,
# a rounder neck, his body under the board's corner. Usage: sh gen2.sh <codex.exe> head|body|neck <ref png> <out png>
C="$1"; WHAT="$2"; REF="$3"; OUT="$4"
STYLE="dark fairy-tale book illustration in pixel-art style, inspired by Inscryption; bold dark ink outlines, flat colour fills with 3-4 shade steps, coarse dithered shading that models ROUND VOLUME (a lit upper-left side, a core shadow, a darker underside), chunky readable shapes, crisp hard edges, no blur, no soft gradients; gloomy and grimy, muted palette; the SAME creature as in the attached picture: cold slate-teal scarred hide with barnacles and clinging weed, pale bone-yellow underside with crosswise folds, amber eye with a slit pupil, long needle teeth"
case "$WHAT" in
head) SUBJ="The HEAD and the first part of the NECK of the ancient plesiosaur, in THREE-QUARTER FRONT view from slightly above: a big menacing reptile head in the LEFT and CENTRE of the picture, turned towards the viewer and tilted DOWN, looking down to the bottom-centre as if at something below it; BOTH amber eyes visible, the near one large; jaws slightly open with long needle teeth showing; heavy brow, scars, barnacles. Behind the head its thick NECK curves away to the RIGHT and leaves the picture HORIZONTALLY through the RIGHT edge near the bottom-right, cut off flat by the right edge; the neck there is about one fifth of the picture's height thick. Strong volume: the head clearly nearer than the neck. Nothing else.";;
body) SUBJ="The BODY of the ancient plesiosaur seen from above and a little from the side, lying low: a broad barrel body with ONE big front flipper spread towards the viewer and the tip of a rear flipper, the back with a row of low bumps, scars, barnacles and weed. Its NECK leaves the body at the TOP-RIGHT and runs HORIZONTALLY out through the RIGHT edge of the picture near the top, cut off flat by the right edge, about one fifth of the picture's height thick. The body fills the LEFT two thirds of the picture and is cut off by the LEFT edge and the BOTTOM edge (it goes on out of the picture, into deep shadow at the bottom). No head. Nothing else.";;
neck) SUBJ="ONE straight piece of the long neck of the ancient plesiosaur, seen from the side and a little from above, lying perfectly HORIZONTAL across the WHOLE width of the picture from the left edge to the right edge, cut off flat by both edges. The SAME thickness all along (about a fifth of the picture's height), centred vertically, no taper, no head, no body, no bend. It must read as a thick ROUND tube: a lit band along the upper back, mottled slate-teal sides, a core shadow, the pale folded underside below, a row of low bumps along the top; scars, a few barnacles, a little weed, spread evenly so the piece can be repeated end to end. Nothing else.";;
esac
P="\$imagegen GENERATE a new image and save it as ONE PNG file. Do not edit any other files, do not run anything else.
The attached image shows the creature and the drawing style to keep: $STYLE.
Subject: $SUBJ
Frame: LANDSCAPE 3:2, 1536x1024. Solid flat magenta #FF00FF background, no shadow on the background, no glow, no particles, no water. No text, no UI, no frame, no border, no watermark.
When done, print the absolute path of the saved image."
R=$(printf '%s' "$P" | "$C" exec --skip-git-repo-check -s read-only -i "$REF" - 2>&1 | grep -o 'C:.*\.png' | tail -1)
if [ -n "$R" ]; then cp "$R" "$OUT" && echo "OK $OUT"; else echo "FAIL $OUT"; fi
